css:
.head{display:flex; align-items:baseline; gap:14px}      /* 密着型 */
.head.spread{justify-content:space-between}                /* 両端型 */
.head h2{font-size:clamp(40px,5.6vw,84px); font-weight:800; letter-spacing:-.02em; margin:0}
.head a{font-size:9px; font-weight:700; letter-spacing:.18em; text-decoration:none; border-bottom:1px solid currentColor; padding:0 6px 4px}
